  /// <summary>
  /// The status of a backup run.
  /// </summary>
  public enum SqlBackupRunStatus {
    /// <summary>
    /// The status of the run is unknown.
    /// </summary>
    [pbr::OriginalName("SQL_BACKUP_RUN_STATUS_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// The backup operation was enqueued.
    /// </summary>
    [pbr::OriginalName("ENQUEUED")] Enqueued = 1,
    /// <summary>
    /// The backup is overdue across a given backup window. Indicates a
    /// problem. Example: Long-running operation in progress during
    /// the whole window.
    /// </summary>
    [pbr::OriginalName("OVERDUE")] Overdue = 2,
    /// <summary>
    /// The backup is in progress.
    /// </summary>
    [pbr::OriginalName("RUNNING")] Running = 3,
    /// <summary>
    /// The backup failed.
    /// </summary>
    [pbr::OriginalName("FAILED")] Failed = 4,
    /// <summary>
    /// The backup was successful.
    /// </summary>
    [pbr::OriginalName("SUCCESSFUL")] Successful = 5,
    /// <summary>
    /// The backup was skipped (without problems) for a given backup
    /// window. Example: Instance was idle.
    /// </summary>
    [pbr::OriginalName("SKIPPED")] Skipped = 6,
    /// <summary>
    /// The backup is about to be deleted.
    /// </summary>
    [pbr::OriginalName("DELETION_PENDING")] DeletionPending = 7,
    /// <summary>
    /// The backup deletion failed.
    /// </summary>
    [pbr::OriginalName("DELETION_FAILED")] DeletionFailed = 8,
    /// <summary>
    /// The backup has been deleted.
    /// </summary>
    [pbr::OriginalName("DELETED")] Deleted = 9,
  }

